@CrossOrigin
@RestController
@RequestMapping("/EvidenceQuery")
public class EvidenceQueryRestController extends BaseSpringRestController {
	
	public EvidenceQueryRestController( EvidenceService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Evidence using a UUID
     * @param		UUID evidenceId
     * @return		Evidence
     */    
    @GetMapping("/load")
    public Evidence load( @RequestParam(required=true) UUID evidenceId ) {
    	Evidence entity = null;

    	try {  
    		entity = service.getEvidence( new EvidenceFetchOneSummary( evidenceId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Evidence using Id " + evidenceId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Evidence business objects
     * @return		Set<Evidence>
     */
    @GetMapping("/")
    public List<Evidence> loadAll() {                
    	List<Evidence> evidenceList = null;
        
    	try {
            // load the Evidence
            evidenceList = service.getAllEvidence();
            
            if ( evidenceList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Evidences" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Evidences ", exc );
        	return null;
        }

        return evidenceList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Evidence evidence = null;
    protected EvidenceService service = null;
    private static final Logger LOGGER = Logger.getLogger(EvidenceQueryRestController.class.getName());
    
}
